import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import LogFileListItem from './LogFileListItem';
export default class LogFileList extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    this.loading = true;
    this.files = [];
    this.state = this.attrs.state;

    // Register refresh callback with the state
    this.state.setRefreshCallback(() => this.refresh());
    this.refresh();
  }
  view() {
    if (this.loading) {
      return m(LoadingIndicator, null);
    }
    return m("div", {
      className: "LogViewerPage--fileListItems"
    }, this.files.map(file => {
      return m(LogFileListItem, {
        file: file,
        state: this.state
      });
    }));
  }
  refresh(clear) {
    if (clear === void 0) {
      clear = true;
    }
    if (clear) {
      this.loading = true;
      this.files = [];
    }
    return this.loadResults().then(this.parseResults.bind(this));
  }
  loadResults() {
    return app.store.find('logs');
  }
  parseResults(results) {
    this.files.push(...results);
    this.loading = false;
    m.redraw();
    return results;
  }
}
flarum.reg.add('ianm-log-viewer', 'admin/components/LogFileList', LogFileList);